import { Component, inject, signal } from '@angular/core';
import { NgOptimizedImage } from '@angular/common';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatBottomSheet } from '@angular/material/bottom-sheet';
import { MatButtonModule } from '@angular/material/button';
import { MatDialog } from '@angular/material/dialog';
import { MatDivider } from '@angular/material/divider';
import { MatIconModule } from '@angular/material/icon';
import { MatListModule } from '@angular/material/list';
import { BreakpointObserver } from '@angular/cdk/layout';
import { Book, BookService } from '../book.service';
import {
  FormatPickSheetComponent,
  FormatPickSheetData,
} from '../format-pick-sheet/format-pick-sheet';

@Component({
  selector: 'app-book-list',
  imports: [NgOptimizedImage, MatListModule, MatButtonModule, MatIconModule, MatDivider],
  styles: [
    `
      .field-error {
        font-size: 0.75rem;
        color: var(--mat-sys-error);
      }
    `,
  ],
  template: `
    <mat-list>
      @for (book of books(); track book.id) {
        <mat-list-item>
          @if (book.default_cover_url) {
            <img
              matListItemAvatar
              [ngSrc]="book.default_cover_url"
              width="40"
              height="40"
              [alt]="book.title + ' cover'"
            />
          }
          <span matListItemTitle class="font-serif">{{ book.title }}</span>
          <span matListItemLine>{{ book.authors.map((a) => a.name).join(', ') }}</span>
          @if (deleteError()?.bookId === book.id) {
            <span matListItemLine class="field-error" role="alert">{{
              deleteError()?.message
            }}</span>
          }
          <span matListItemMeta>
            <button
              mat-stroked-button
              [attr.aria-label]="'Mark ' + book.title + ' as reading'"
              (click)="openFormatPicker(book)"
            >
              Mark as reading
            </button>
            <button
              mat-icon-button
              [attr.aria-label]="'Delete ' + book.title"
              (click)="deleteBook(book)"
            >
              <mat-icon>delete</mat-icon>
            </button>
          </span>
        </mat-list-item>
        @if (!$last) {
          <mat-divider />
        }
      }
    </mat-list>
  `,
})
export class BookListComponent {
  private readonly bookService = inject(BookService);
  private readonly bottomSheet = inject(MatBottomSheet);
  private readonly dialog = inject(MatDialog);
  private readonly breakpointObserver = inject(BreakpointObserver);

  protected readonly books = toSignal(this.bookService.books$, { initialValue: [] });
  protected readonly deleteError = signal<{ bookId: string; message: string } | null>(null);

  protected openFormatPicker(book: Book): void {
    const data: FormatPickSheetData = {
      bookId: book.id,
      title: book.title,
      cover_url: book.default_cover_url,
      default_audio_minutes: book.default_audio_minutes,
    };

    if (this.breakpointObserver.isMatched('(max-width: 599px)')) {
      this.bottomSheet.open(FormatPickSheetComponent, { data });
    } else {
      this.dialog.open(FormatPickSheetComponent, { data });
    }
  }

  protected deleteBook(book: Book): void {
    if (!confirm(`Delete "${book.title}"? This can't be undone.`)) {
      return;
    }
    this.deleteError.set(null);
    this.bookService.deleteBook(book.id).subscribe({
      next: () => {
        this.bookService.reloadBooks();
      },
      error: (err) => {
        if (err.status === 409) {
          this.deleteError.set({ bookId: book.id, message: err.error?.detail ?? 'Conflict' });
        }
      },
    });
  }
}

import { CommonModule } from '@angular/common';
import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'storybook-button',
  standalone: true,
  imports: [CommonModule],
  template: `
    <button
      type="button"
      (click)="onClick.emit($event)"
      [ngClass]="classes"
      [ngStyle]="{ 'background-color': backgroundColor }"
    >
      {{ label }}
    </button>
  `,
  styleUrls: ['./button.css'],
})
export class ButtonComponent {
  /** Is this the principal call to action on the page? */
  @Input()
  primary = false;

  /** What background color to use */
  @Input()
  backgroundColor?: string;

  /** How large should the button be? */
  @Input()
  size: 'small' | 'medium' | 'large' = 'medium';

  /**
   * Button contents
   *
   * @required
   */
  @Input()
  label = 'Button';

  /** Optional click handler */
  @Output()
  onClick = new EventEmitter<Event>();

  public get classes(): string[] {
    const mode = this.primary ? 'storybook-button--primary' : 'storybook-button--secondary';

    return ['storybook-button', `storybook-button--${this.size}`, mode];
  }
}

