/* Dark band on an otherwise light page — the parent LandingComponent fixes
   color-scheme to light for the rest of the page (see landing.css), but
   scoping `color-scheme: dark` to just this subtree flips every
   `light-dark()`-based --color-* token used inside it to its dark value,
   with no separate dark stylesheet. */

.insights-band {
  color-scheme: dark;
  background: var(--color-background);
  color: var(--color-text);
  margin-top: 56px;
}

