.mdc-dialog__title {
  padding: 0 !important;
  margin: 0 !important;
  font: 600 1.125rem/1.25 var(--font-serif) !important;
  color: var(--color-text) !important;
}
.mdc-dialog__title::before {
  display: none;
}

