import { Component, inject } from '@angular/core';
import { DatePipe, NgOptimizedImage } from '@angular/common';
import { toSignal } from '@angular/core/rxjs-interop';
import { RouterLink } from '@angular/router';
import { MatBottomSheet } from '@angular/material/bottom-sheet';
import { MatButtonModule } from '@angular/material/button';
import { MatDialog } from '@angular/material/dialog';
import { MatDivider } from '@angular/material/divider';
import { MatIconModule } from '@angular/material/icon';
import { MatListModule } from '@angular/material/list';
import { BreakpointObserver } from '@angular/cdk/layout';
import { Engagement, EngagementService, Review } from '../engagement.service';
import { formatIcon } from '../format-icon';
import { ReviewSheetComponent, ReviewSheetData } from '../review-sheet/review-sheet';

@Component({
  selector: 'app-read',
  imports: [
    MatListModule,
    MatIconModule,
    MatDivider,
    NgOptimizedImage,
    DatePipe,
    MatButtonModule,
    RouterLink,
  ],
  styles: [
    `
      .format-icon {
        font-size: 14px;
        width: 14px;
        height: 14px;
        vertical-align: middle;
      }
    `,
  ],
  template: `
    <mat-list>
      @for (engagement of finishedEngagements(); track engagement.id) {
        <mat-list-item>
          @if (engagement.cover_url) {
            <img
              matListItemAvatar
              [ngSrc]="engagement.cover_url"
              width="40"
              height="40"
              [alt]="engagement.book.title + ' cover'"
            />
          }
          <span matListItemTitle class="font-serif">{{ engagement.book.title }}</span>
          <span matListItemLine>
            {{ engagement.book.authors.map((a) => a.name).join(', ') }}
            @if (engagement.formats[0]) {
              <mat-icon
                class="format-icon"
                aria-hidden="false"
                [aria-label]="'Format: ' + engagement.formats[0]"
                >{{ formatIcon(engagement.formats[0]) }}</mat-icon
              >
            }
          </span>
          @if (engagement.finished_on) {
            <span matListItemLine>
              Finished {{ engagement.finished_on | date: 'mediumDate' : 'UTC' }}</span
            >
          }
          @if (reviewSummary(engagement.review); as summary) {
            <span
              matListItemLine
              [attr.aria-label]="'Review summary for ' + engagement.book.title"
              >{{ summary }}</span
            >
          }
          <span matListItemMeta>
            <button
              mat-icon-button
              [routerLink]="['/engagement', engagement.id]"
              [attr.aria-label]="'View history for ' + engagement.book.title"
            >
              <mat-icon>history</mat-icon>
            </button>
            <button
              mat-button
              (click)="openReviewSheet(engagement)"
              [attr.aria-label]="
                (engagement.review ? 'Edit' : 'Add') + ' review for ' + engagement.book.title
              "
            >
              {{ engagement.review ? 'Edit review' : 'Add review' }}
            </button>
            <button
              mat-icon-button
              [attr.aria-label]="'Delete ' + engagement.book.title"
              (click)="deleteEngagement(engagement)"
            >
              <mat-icon>delete</mat-icon>
            </button>
          </span>
        </mat-list-item>
        @if (!$last) {
          <mat-divider />
        }
      } @empty {
        <p>No finished books yet.</p>
      }
    </mat-list>
  `,
})
export class ReadComponent {
  protected readonly formatIcon = formatIcon;

  private readonly engagementService = inject(EngagementService);
  private readonly bottomSheet = inject(MatBottomSheet);
  private readonly dialog = inject(MatDialog);
  private readonly breakpointObserver = inject(BreakpointObserver);

  protected readonly finishedEngagements = toSignal(
    this.engagementService.engagements('finished'),
    {
      initialValue: [],
    },
  );

  protected reviewSummary(review: Review | null): string | null {
    if (!review) return null;
    return (
      [review.rating ? `${review.rating} ★` : null, review.body].filter(Boolean).join(' · ') || null
    );
  }

  protected openReviewSheet(engagement: Engagement): void {
    const data: ReviewSheetData = {
      engagementId: engagement.id,
      title: engagement.book.title,
      cover_url: engagement.cover_url,
      review: engagement.review,
    };

    if (this.breakpointObserver.isMatched('(max-width: 599px)')) {
      this.bottomSheet.open(ReviewSheetComponent, { data });
    } else {
      this.dialog.open(ReviewSheetComponent, { data });
    }
  }

  protected deleteEngagement(engagement: Engagement): void {
    if (!confirm("Delete this engagement? This can't be undone.")) {
      return;
    }
    this.engagementService.deleteEngagement(engagement.id).subscribe(() => {
      this.engagementService.reloadEngagements();
    });
  }
}

import { Component, inject, signal } from '@angular/core';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { MatBottomSheetRef, MAT_BOTTOM_SHEET_DATA } from '@angular/material/bottom-sheet';
import { MatButtonModule } from '@angular/material/button';
import { MatDialogRef, MAT_DIALOG_DATA, MatDialogTitle } from '@angular/material/dialog';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { EngagementService, Review } from '../engagement.service';

export interface ReviewSheetData {
  engagementId: string;
  title: string;
  cover_url: string | null;
  review: Review | null;
}

@Component({
  selector: 'app-review-sheet',
  imports: [
    ReactiveFormsModule,
    MatButtonModule,
    MatFormFieldModule,
    MatInputModule,
    MatDialogTitle,
  ],
  template: `
    <div
      style="display: flex; flex-direction: column; align-items: center; padding: 16px; gap: 12px;"
    >
      @if (data.cover_url) {
        <img
          [src]="data.cover_url"
          [alt]="data.title + ' cover'"
          style="height: 120px; width: auto;"
        />
      }
      <h2 mat-dialog-title style="margin: 0; text-align: center;">{{ data.title }}</h2>

      <div style="width: 100%;">
        <p id="rating-label" style="margin: 0 0 4px 0;">Rating (optional)</p>
        <div
          style="display: flex; align-items: center; gap: 8px;"
          role="group"
          aria-labelledby="rating-label"
        >
          <select
            [formControl]="wholeControl"
            [attr.aria-label]="'Whole number rating for ' + data.title"
          >
            <option [ngValue]="null">—</option>
            @for (n of [1, 2, 3, 4, 5]; track n) {
              <option [ngValue]="n">{{ n }}</option>
            }
          </select>
          <span aria-hidden="true">.</span>
          <select
            [formControl]="fractionControl"
            [attr.aria-label]="'Fractional rating for ' + data.title"
          >
            <option [ngValue]="0">00</option>
            <option [ngValue]="0.25" [disabled]="wholeControl.value === 5">25</option>
            <option [ngValue]="0.5" [disabled]="wholeControl.value === 5">50</option>
            <option [ngValue]="0.75" [disabled]="wholeControl.value === 5">75</option>
          </select>
          <span aria-hidden="true">★</span>
        </div>
      </div>

      <mat-form-field style="width: 100%;">
        <mat-label>Review (optional)</mat-label>
        <textarea
          matInput
          rows="4"
          [formControl]="bodyControl"
          [attr.aria-label]="'Review text for ' + data.title"
        ></textarea>
      </mat-form-field>

      @if (error()) {
        <p role="alert">{{ error() }}</p>
      }

      <button
        mat-flat-button
        style="width: 100%;"
        [disabled]="saving()"
        (click)="save()"
        [attr.aria-label]="'Save review for ' + data.title"
      >
        {{ saving() ? 'Saving…' : 'Save' }}
      </button>
      <button mat-button style="width: 100%;" [disabled]="saving()" (click)="close()">
        Cancel
      </button>
    </div>
  `,
})
export class ReviewSheetComponent {
  private readonly dialogRef = inject(MatDialogRef, { optional: true });
  private readonly bottomSheetRef = inject(MatBottomSheetRef, { optional: true });
  protected readonly data: ReviewSheetData =
    inject<ReviewSheetData>(MAT_DIALOG_DATA, { optional: true }) ??
    inject<ReviewSheetData>(MAT_BOTTOM_SHEET_DATA);
  private readonly engagementService = inject(EngagementService);

  protected readonly saving = signal(false);
  protected readonly error = signal<string | null>(null);

  protected readonly wholeControl: FormControl<number | null>;
  protected readonly fractionControl: FormControl<number>;
  protected readonly bodyControl: FormControl<string>;

  constructor() {
    const existingRating =
      this.data.review?.rating != null ? parseFloat(this.data.review.rating) : null;
    const whole = existingRating !== null ? Math.floor(existingRating) : null;
    const fraction = existingRating !== null ? existingRating - Math.floor(existingRating) : 0;

    this.wholeControl = new FormControl<number | null>(whole);
    this.fractionControl = new FormControl<number>(fraction, { nonNullable: true });
    this.bodyControl = new FormControl<string>(this.data.review?.body ?? '', {
      nonNullable: true,
    });

    if (whole === null) {
      this.fractionControl.disable();
    }

    this.wholeControl.valueChanges.subscribe((val) => {
      if (val === null) {
        this.fractionControl.disable();
      } else {
        this.fractionControl.enable();
        if (val === 5) {
          this.fractionControl.setValue(0);
        }
      }
    });
  }

  protected save(): void {
    if (this.saving()) return;
    this.saving.set(true);
    this.error.set(null);

    const whole = this.wholeControl.value;
    const rating = whole !== null ? whole + this.fractionControl.value : null;
    const bodyRaw = this.bodyControl.value.trim();
    const body = bodyRaw === '' ? null : bodyRaw;

    this.engagementService.upsertReview(this.data.engagementId, rating, body).subscribe({
      next: () => {
        this.engagementService.reloadEngagements();
        this.close();
      },
      error: () => {
        this.saving.set(false);
        this.error.set('Failed to save. Please try again.');
      },
    });
  }

  protected close(): void {
    this.dialogRef?.close();
    this.bottomSheetRef?.dismiss();
  }
}

